(()=>{const host=document.getElementById('L04-lab');if(!host)return;const zh=document.documentElement.lang.startsWith('zh'),tr=(z,e)=>zh?z:e,defaults={pulse:2,sphase:8,cycling:.75};let p={...defaults},state={};const controls={};for(const k of Object.keys(p)){controls[k]=host.querySelector('#L04-'+k);controls[k].addEventListener('input',()=>set({[k]:Number(controls[k].value)}));}function set(v){for(const k in p)if(k in v)p[k]=Math.max(Number(controls[k].min),Math.min(Number(controls[k].max),Number(v[k])));draw();return state;}
function draw(){for(const k in p){controls[k].value=p[k];host.querySelector('[data-value="'+k+'"]').textContent=k==='cycling'?(100*p[k]).toFixed(0)+'%':p[k];}const fraction=p.cycling*Math.min(1,(p.sphase+p.pulse)/24);state={...p,fraction,expectedPositive:fraction*480};const x=v=>90+24*v,y=f=>460-210*f;let covered='';for(let t=0;t<24;t+=.1){let marked=false;for(let k=0;k<2;k++)if(Math.min(t+p.pulse,8+p.sphase+k*24)>Math.max(t,8+k*24))marked=true;if(marked)covered+=`<rect x="${x(t)}" y="130" width="2.5" height="25" fill="#cd803f"/>`;}
let curve='';for(let t=0;t<=20;t+=.1)curve+=(curve?'L':'M')+(90+28.8*t).toFixed(2)+','+y(p.cycling*Math.min(1,(p.sphase+t)/24)).toFixed(2);let ticks='';for(const t of [0,4,8,12,16,20,24])ticks+=`<text x="${x(t)}" y="182" text-anchor="middle">${t}</text>`;for(const f of [0,.25,.5,.75,1])ticks+=`<text x="75" y="${y(f)+5}" text-anchor="end">${100*f}%</text><line x1="90" x2="666" y1="${y(f)}" y2="${y(f)}" stroke="#dbe4e7"/>`;for(const t of [0,4,8,12,16,20])ticks+=`<text x="${90+28.8*t}" y="486" text-anchor="middle">${t}</text>`;host.querySelector('svg').innerHTML=`<rect width="760" height="540" fill="#faf9f5"/><g fill="#263e48" font-size="17"><text x="380" y="27" text-anchor="middle">${tr('周期 24 h；固定追踪单位，起始相位均匀','24 h cycle; fixed tracking units, uniform initial phases')}</text><text x="90" y="62">${tr('S 阶段的位置','S-phase interval')}</text><rect x="90" y="72" width="576" height="25" fill="#dce7eb"/><rect x="${x(8)}" y="72" width="${24*p.sphase}" height="25" fill="#3c8a6a"/><text x="90" y="121">${tr('可能在脉冲内获得标记的起始相位','Starting phases that can acquire label during the pulse')}</text>${covered}${ticks}<text x="380" y="208" text-anchor="middle">${tr('起始相位 / h','Starting phase / h')}</text><path d="${curve}" fill="none" stroke="#186e83" stroke-width="3"/><circle cx="${90+28.8*p.pulse}" cy="${y(fraction)}" r="7" fill="#cd803f"/><text x="380" y="526" text-anchor="middle">${tr('正脉冲时长 / h（零处表示右侧极限）','Positive pulse / h (zero marks the right-hand limit)')}</text></g>`;host.querySelector('[data-result]').textContent=tr(`理想覆盖比例 ${(fraction*100).toFixed(2)}%；480 个固定追踪单位中对应 ${state.expectedPositive.toFixed(1)} 个的期望值。此模型不加入分裂后新增分母，也不设置检测阈值。`,`Ideal coverage ${(fraction*100).toFixed(2)}%; expected ${state.expectedPositive.toFixed(1)} of 480 fixed tracking units. The model does not add daughter nuclei to the denominator or impose a detection threshold.`);}
host.querySelector('#L04-longer').addEventListener('click',()=>set({pulse:Math.min(20,p.pulse+2)}));host.querySelector('#L04-reset').addEventListener('click',()=>set(defaults));window.CourseLab={set,state:()=>({...state}),reset:()=>set(defaults)};draw();})();
